#!/usr/bin/env python3
"""Adds what OneSource Connect needs to the host projects generated by `flutter create`.

Run from the project root after `flutter create` (tool/bootstrap.sh does this). Safe to run twice.
"""
import pathlib
import plistlib
import re
import sys

root = pathlib.Path(__file__).resolve().parent.parent
changed = []

# ---- iOS: usage descriptions, languages, display name -------------------------------------------------------
plist_path = root / 'ios' / 'Runner' / 'Info.plist'
if plist_path.exists():
    with plist_path.open('rb') as f:
        plist = plistlib.load(f)
    plist.update({
        'CFBundleDisplayName': 'OneSource Connect',
        'CFBundleLocalizations': ['en', 'ar'],
        'NSFaceIDUsageDescription': 'Unlock OneSource Connect with Face ID. The app never receives an image of your face.',
        'NSCameraUsageDescription': 'Take photos to attach to a help request or as trip proof.',
        'NSPhotoLibraryUsageDescription': 'Choose photos to attach to a help request.',
        'NSLocationWhenInUseUsageDescription': 'Your company records where attendance is marked and where trip milestones happen.',
        'LSApplicationQueriesSchemes': ['https', 'tel'],
        # onesource://… links (lib/core/links/deep_links.dart); handled by app_links, not Flutter's own deep linking
        'CFBundleURLTypes': [{'CFBundleURLName': 'qa.onesource.connect', 'CFBundleURLSchemes': ['onesource']}],
        'FlutterDeepLinkingEnabled': False,
        # push: remote notifications in the background (also enable Push Notifications capability in Xcode)
        'UIBackgroundModes': ['remote-notification'],
    })
    with plist_path.open('wb') as f:
        plistlib.dump(plist, f)
    changed.append(str(plist_path.relative_to(root)))
else:
    print('ios/Runner/Info.plist not found: run flutter create first', file=sys.stderr)

# ---- iOS: minimum version 13 (geolocator, local_auth) -------------------------------------------------------
podfile = root / 'ios' / 'Podfile'
if podfile.exists():
    text = podfile.read_text()
    new = re.sub(r"^#?\s*platform :ios, '[0-9.]+'", "platform :ios, '13.0'", text, flags=re.M)
    if new != text:
        podfile.write_text(new)
        changed.append(str(podfile.relative_to(root)))

# ---- Android: minSdk 24 (local_auth, geolocator) and an AppCompat launch theme ------------------------------
for name in ('build.gradle.kts', 'build.gradle'):
    gradle = root / 'android' / 'app' / name
    if gradle.exists():
        text = gradle.read_text()
        new = re.sub(r'minSdk(Version)?\s*=?\s*flutter\.minSdkVersion', lambda m: 'minSdk = 24' if name.endswith('kts') else 'minSdkVersion 24', text)
        new = re.sub(r'compileSdk(Version)?\s*=?\s*flutter\.compileSdkVersion', lambda m: 'compileSdk = 36' if name.endswith('kts') else 'compileSdkVersion 36', new)
        if new != text:
            gradle.write_text(new)
            changed.append(str(gradle.relative_to(root)))

# ---- Android: release signing from key.properties --------------------------------------------------------------
for name in ('build.gradle.kts', 'build.gradle'):
    gradle = root / 'android' / 'app' / name
    if gradle.exists():
        text = gradle.read_text()
        line = 'apply(from = "signing.gradle")' if name.endswith('kts') else "apply from: 'signing.gradle'"
        if 'signing.gradle' not in text:
            gradle.write_text(text.rstrip() + '\n\n// release signing from key.properties (tool/configure_platforms.py)\n' + line + '\n')
            changed.append(str(gradle.relative_to(root)) + ' (signing)')

# ---- Android: every plugin builds against the same compileSdk as the app (Flutter 3.44+ needs 36) -------------
for name, block in (
    ('build.gradle.kts', '''
// all plugins compile against Android 36 (tool/configure_platforms.py)
subprojects {
    afterEvaluate {
        extensions.findByName("android")?.withGroovyBuilder { "compileSdkVersion"(36) }
    }
}
'''),
    ('build.gradle', '''
// all plugins compile against Android 36 (tool/configure_platforms.py)
subprojects {
    afterEvaluate { p ->
        if (p.extensions.findByName("android") != null) { p.android.compileSdkVersion 36 }
    }
}
'''),
):
    gradle = root / 'android' / name
    if gradle.exists():
        text = gradle.read_text()
        if 'compileSdkVersion"(36)' not in text and 'compileSdkVersion 36' not in text:
            # must be registered before evaluationDependsOn(":app") evaluates the projects
            marker = 'subprojects {\n    project.evaluationDependsOn'
            i = text.find(marker)
            text = (text[:i] + block.lstrip('\n') + '\n' + text[i:]) if i >= 0 else (block + '\n' + text)
            gradle.write_text(text)
            changed.append(str(gradle.relative_to(root)) + ' (compileSdk 36)')

# ---- iOS: push entitlement ------------------------------------------------------------------------------------
ent = root / 'ios' / 'Runner' / 'Runner.entitlements'
pbx = root / 'ios' / 'Runner.xcodeproj' / 'project.pbxproj'
if (root / 'ios' / 'Runner').exists() and not ent.exists():
    with ent.open('wb') as f:
        plistlib.dump({'aps-environment': 'development'}, f)  # Xcode switches to production for App Store builds
    changed.append(str(ent.relative_to(root)))
if pbx.exists():
    text = pbx.read_text()
    if 'CODE_SIGN_ENTITLEMENTS' not in text:
        # only the Runner target's configurations (they carry the app bundle id without "RunnerTests")
        new = re.sub(r'^([ \t]*)PRODUCT_BUNDLE_IDENTIFIER = ([^;]*?);$', lambda m: m.group(0) if 'RunnerTests' in m.group(2) else m.group(0) + '\n' + m.group(1) + 'CODE_SIGN_ENTITLEMENTS = Runner/Runner.entitlements;', text, flags=re.M)
        if new != text:
            pbx.write_text(new)
            changed.append(str(pbx.relative_to(root)))

print('updated:', ', '.join(changed) if changed else 'nothing')
